# Wires the prefix into every shell, not just zsh. Two generated files:
#
#   share/mpkg/env.sh          environment variables only, POSIX sh. Safe to
#                              source any number of times from any shell.
#   share/mpkg/interactive.sh  prompt, plugins, shell functions: things that
#                              are not inherited by child processes.
#
# and a marked block in each startup file that applies:
#
#   ~/.profile        env          sh, dash, and bash when it has no ~/.bash_profile
#   ~/.bash_profile   env          only if it already exists (creating one would
#                                  make bash stop reading ~/.profile)
#   ~/.bashrc         env + interactive   interactive non-login bash
#   ~/.zprofile       env          zsh login shells (after macOS's path_helper)
#   ~/.zshrc          env + interactive   interactive zsh
#
# bash/zsh files are touched only when that shell is installed. Only mpkg's own
# block is ever replaced; the rest of each file is left alone.

mpkg_inherit pkgcommon

MPKG_TITLE="Shell configuration"
MPKG_DESC="mpkg env file plus startup-file blocks for sh, bash and zsh"
MPKG_KIND="config"
MPKG_UNVERSIONED=1
MPKG_PROBE_CMD="sh"
MPKG_DEPENDS=(starship)

MPKG_ENV_FILE="${MPKG_PREFIX}/share/mpkg/env.sh"
MPKG_RC_FILE="${MPKG_PREFIX}/share/mpkg/interactive.sh"
MPKG_MARK_BEGIN="# >>> mpkg >>>"
MPKG_MARK_END="# <<< mpkg <<<"

# Oh My Zsh only where there is a zsh to run it.
mpkg_describe() {
    command -v zsh >/dev/null 2>&1 && MPKG_DEPENDS+=(oh-my-zsh)
    return 0
}

mpkg_run() {
    mpkg::shell_write_env || return 1
    mpkg::shell_write_rc  || return 1
    local f kind
    while read -r f kind; do
        mpkg::shell_patch_rc "${f}" "${kind}" || return 1
    done < <(mpkg::shell_targets)
    MPKG_VERSION="present"
    MPKG_DEST_NAME=""
    MPKG_STATUS="installed"
}

# "<file> env|all" for every startup file this machine's shells read.
mpkg::shell_targets() {
    printf '%s env\n' "${HOME}/.profile"
    [[ -f "${HOME}/.bash_profile" ]] && printf '%s env\n' "${HOME}/.bash_profile"
    if command -v bash >/dev/null 2>&1; then
        printf '%s all\n' "${HOME}/.bashrc"
    fi
    if command -v zsh >/dev/null 2>&1; then
        printf '%s env\n' "${ZDOTDIR:-${HOME}}/.zprofile"
        printf '%s all\n' "${ZDOTDIR:-${HOME}}/.zshrc"
    fi
}

mpkg::shell_write_env() {
    mkdir -p "$(dirname "${MPKG_ENV_FILE}")" || return 1
    mpkg::step "writing ${MPKG_ENV_FILE}"
    {
        printf '# Generated by mpkg on %s. Edits are overwritten.\n' "$(date -u +%F)"
        printf '# Environment only, POSIX sh: sourced by sh, bash and zsh, possibly\n'
        printf '# more than once (login shell, then interactive shell).\n'
        printf '#\n'
        printf '# Every entry is checked when the shell starts, not when this file was\n'
        printf '# written: a variable is only touched for something that is installed\n'
        printf '# now, and installing it later needs no new env file.\n\n'
        printf 'export MPKG_PREFIX="%s"\n\n' "${MPKG_PREFIX}"
        cat <<'BODY'
# Move (or add) an existing directory to the front of a colon list; a missing
# one is left out. Moving, not just adding, matters on macOS: /etc/zprofile's
# path_helper puts the system directories back in front of ours.
mpkg_path_prepend() {
    [ -d "$2" ] || return 0
    eval "_mpkg_cur=\":\${$1:-}:\""
    while :; do
        case "${_mpkg_cur}" in
            *":$2:"*) _mpkg_cur="${_mpkg_cur%%:"$2":*}:${_mpkg_cur#*:"$2":}" ;;
            *) break ;;
        esac
    done
    _mpkg_cur="${_mpkg_cur#:}"; _mpkg_cur="${_mpkg_cur%:}"
    if [ -n "${_mpkg_cur}" ]; then eval "export $1=\"\$2:\${_mpkg_cur}\""
    else                           eval "export $1=\"\$2\""
    fi
    unset _mpkg_cur
}

# The compiler and linker search lists change every build on the machine, so
# they get a directory only when something was installed into it. (No glob:
# zsh aborts on one that matches nothing.)
mpkg_build_prepend() {
    [ -n "$(ls -A "$2" 2>/dev/null)" ] && mpkg_path_prepend "$1" "$2"
}

mpkg_path_prepend PATH            "${HOME}/.cargo/bin"
mpkg_path_prepend PATH            "${MPKG_PREFIX}/bin"
mpkg_build_prepend CPATH           "${MPKG_PREFIX}/include"
mpkg_build_prepend LIBRARY_PATH    "${MPKG_PREFIX}/lib64"
mpkg_build_prepend LIBRARY_PATH    "${MPKG_PREFIX}/lib"
mpkg_build_prepend PKG_CONFIG_PATH "${MPKG_PREFIX}/lib64/pkgconfig"
mpkg_build_prepend PKG_CONFIG_PATH "${MPKG_PREFIX}/lib/pkgconfig"
BODY
        # dyld ignores LD_LIBRARY_PATH; macOS binaries find the prefix by rpath.
        if [[ "${_OS}" != "macos" ]]; then
            printf 'mpkg_build_prepend LD_LIBRARY_PATH "${MPKG_PREFIX}/lib64"\n'
            printf 'mpkg_build_prepend LD_LIBRARY_PATH "${MPKG_PREFIX}/lib"\n'
        fi
        cat <<'BODY'

# A trailing ':' keeps man's built-in search path after ours.
if [ -d "${MPKG_PREFIX}/share/man" ]; then
    case ":${MANPATH:-}:" in
        *":${MPKG_PREFIX}/share/man:"*) ;;
        *) export MANPATH="${MPKG_PREFIX}/share/man:${MANPATH:-}" ;;
    esac
fi

# GTK (zathura) finds its GSettings schemas through XDG_DATA_DIRS. Unset means
# the spec's default, which has to be kept when ours is added.
if [ -d "${MPKG_PREFIX}/share/glib-2.0/schemas" ]; then
    [ -n "${XDG_DATA_DIRS:-}" ] || export XDG_DATA_DIRS="/usr/local/share:/usr/share"
    mpkg_path_prepend XDG_DATA_DIRS "${MPKG_PREFIX}/share"
fi

# JDK (mpkg install jdk)
[ -x "${MPKG_PREFIX}/libexec/jdk/bin/java" ] && export JAVA_HOME="${MPKG_PREFIX}/libexec/jdk"

# Starship preset
[ -f "${HOME}/.config/starship/jetpack.toml" ] \
    && export STARSHIP_CONFIG="${HOME}/.config/starship/jetpack.toml"

# Node (mpkg install nodejs, through nvm). nvm itself is loaded only by
# interactive.sh; without a node on PATH every other process -- an editor
# started from a GUI, git hooks, `sh -c` -- would have none, and node-based
# tools (pyright, bash-language-server, copilot) fail with "env: node: No such
# file". So the newest installed node goes on PATH here; nvm.sh, where it is
# loaded, still switches to its default.
if [ -d "${HOME}/.nvm" ]; then
    export NVM_DIR="${HOME}/.nvm"
    if ! command -v node >/dev/null 2>&1 && [ -d "${NVM_DIR}/versions/node" ]; then
        _mpkg_node="$(ls "${NVM_DIR}/versions/node" 2>/dev/null | sed -n 's/^v\([0-9.]*\)$/\1/p' \
                      | sort -t. -k1,1n -k2,2n -k3,3n | tail -n 1)"
        [ -n "${_mpkg_node}" ] && mpkg_path_prepend PATH "${NVM_DIR}/versions/node/v${_mpkg_node}/bin"
        unset _mpkg_node
    fi
fi
BODY
        if [[ -n "${MPKG_CA_BUNDLE}" ]]; then
            printf '\nif [ -r "%s" ]; then\n' "${MPKG_CA_BUNDLE}"
            printf '    export SSL_CERT_FILE="%s"\n    export CURL_CA_BUNDLE="%s"\nfi\n' \
                   "${MPKG_CA_BUNDLE}" "${MPKG_CA_BUNDLE}"
        fi
        printf '\nunset -f mpkg_path_prepend mpkg_build_prepend\n'
    } > "${MPKG_ENV_FILE}"
}

mpkg::shell_write_rc() {
    mpkg::step "writing ${MPKG_RC_FILE}"
    {
        printf '# Generated by mpkg on %s. Edits are overwritten.\n' "$(date -u +%F)"
        printf '# Interactive bash/zsh setup; the environment is in env.sh.\n\n'
        cat <<'BODY'
# mpkg environments:  mpkg_activate <name>  /  mpkg_deactivate
mpkg_activate() {
    if [ -f "${MPKG_PREFIX}/envs/$1/activate" ]; then . "${MPKG_PREFIX}/envs/$1/activate"
    else echo "mpkg_activate: no environment '$1'" >&2; return 1
    fi
}

# Oh My Zsh
if [ -n "${ZSH_VERSION:-}" ] && [ -d "${HOME}/.oh-my-zsh" ]; then
    export ZSH="${HOME}/.oh-my-zsh"
    ZSH_THEME="robbyrussell"
    plugins=(git zsh-autosuggestions zsh-syntax-highlighting)
    . "${ZSH}/oh-my-zsh.sh"
fi

# Starship prompt
if command -v starship >/dev/null 2>&1; then
    if [ -n "${ZSH_VERSION:-}" ]; then eval "$(starship init zsh)"
    elif [ -n "${BASH_VERSION:-}" ]; then eval "$(starship init bash)"
    fi
fi

# nvm
[ -s "${NVM_DIR:-${HOME}/.nvm}/nvm.sh" ] && . "${NVM_DIR:-${HOME}/.nvm}/nvm.sh"

# RVM (last: it wants its own PATH entries first)
[ -s "${HOME}/.rvm/scripts/rvm" ] && . "${HOME}/.rvm/scripts/rvm"
BODY
    } > "${MPKG_RC_FILE}"
}

# Drop mpkg's block from <file>, leaving everything else as it was.
mpkg::shell_strip_block() {
    local rc="$1" tmp
    [[ -f "${rc}" ]] && grep -qF "${MPKG_MARK_BEGIN}" "${rc}" || return 0
    tmp="$(mktemp "${rc}.mpkg.XXXXXX")" || return 1
    awk -v b="${MPKG_MARK_BEGIN}" -v e="${MPKG_MARK_END}" \
        'index($0,b){s=1} !s{print} index($0,e){s=0}' "${rc}" > "${tmp}" \
        && cat "${tmp}" > "${rc}"      # cat, not mv: keep a symlinked rc a symlink
    rm -f "${tmp}"
}

# patch_rc <file> env|all
mpkg::shell_patch_rc() {
    local rc="$1" kind="$2"
    if [[ -f "${rc}" ]] && grep -qF "${MPKG_MARK_BEGIN}" "${rc}"; then
        mpkg::step "refreshing the mpkg block in ${rc}"
        mpkg::shell_strip_block "${rc}" || return 1
    else
        mpkg::step "adding an mpkg block to ${rc}"
        [[ -s "${rc}" ]] && cp "${rc}" "${rc}.mpkg-backup.$(date +%s)"
    fi
    # The marker must start a line of its own.
    [[ -s "${rc}" && -n "$(tail -c 1 "${rc}")" ]] && printf '\n' >> "${rc}"
    {
        printf '%s\n' "${MPKG_MARK_BEGIN}"
        printf '[ -f "%s" ] && . "%s"\n' "${MPKG_ENV_FILE}" "${MPKG_ENV_FILE}"
        [[ "${kind}" == all ]] && \
            printf '[ -f "%s" ] && . "%s"\n' "${MPKG_RC_FILE}" "${MPKG_RC_FILE}"
        printf '%s\n' "${MPKG_MARK_END}"
    } >> "${rc}"
}

mpkg_link() { return 0; }

# Every file that may carry a block, whether or not that shell is still here.
mpkg_remove() {
    local rc
    for rc in "${HOME}/.profile" "${HOME}/.bash_profile" "${HOME}/.bashrc" \
              "${ZDOTDIR:-${HOME}}/.zprofile" "${ZDOTDIR:-${HOME}}/.zshrc"; do
        mpkg::shell_strip_block "${rc}"
    done
    rm -f "${MPKG_ENV_FILE}" "${MPKG_RC_FILE}"
}
